DEFAULT_TABLE_PREVIEW_LIMIT = 10
DEFAULT_INTERMEDIATE_PREVIEW_LIMIT = 3
MAX_INTERMEDIATE_TABLE_COUNT = 8
# 중간 결과는 실행 payload에 최대 5행만 보관합니다. 이 상한은 답변 모델과
