from __future__ import annotations

import json
from copy import deepcopy
from datetime import datetime, timezone
from importlib import import_module
from typing import Any

from lfx.custom.custom_component.component import Component
from lfx.io import DataInput, DropdownInput, MessageTextInput, Output
from lfx.schema.data import Data

DEFAULT_DATABASE = "datagov"
DEFAULT_SESSION_COLLECTION = "agent_v4_session_states"
DEFAULT_PREVIEW_ROW_LIMIT = 5
DEFAULT_HISTORY_LIMIT = 10
ENABLED_OPTIONS = ["true", "false"]
METADATA_QA_INVENTORY_CONTRACT_VERSION = "metadata_qa.inventory.v1"
MAX_METADATA_QA_INVENTORY_DATASETS = 50
RUNTIME_BUFFER_KEYS = {
    "runtime_sources",
    "_runtime_rows_by_alias",
    "_full_result_rows",
    "_runtime_result_rows",
}


# 주요 함수: 현재 응답의 next state를 세션 문서에 원자적으로 갱신합니다.
# Langflow 클래스와 단위 테스트가 같은 업무 규칙을 쓰도록 일반 Python 값 중심으로 처리합니다.
def write_session_state(
    response_payload_value: Any,
    mongo_uri: Any = "",
    mongo_database: Any = "",
    session_collection_name: Any = "",
    enabled: Any = "true",
    preview_row_limit: Any = "5",
    history_limit: Any = "10",
) -> dict[str, Any]:
    payload = _payload(response_payload_value)
    response = _response_view(payload)
    state = _state_from_response(payload, response)
    state_guard, guard_present = _session_state_guard(payload, response)
    session = _session_id_from_payload(payload) or _session_id_from_payload(response) or _session_id_from_state(state)
    preview_limit = _positive_int(preview_row_limit, DEFAULT_PREVIEW_ROW_LIMIT)
    max_history = _positive_int(history_limit, DEFAULT_HISTORY_LIMIT)
    collection_name = _collection_name(session_collection_name)
    status: dict[str, Any] = {
        "stage": "01_mongodb_session_state_writer",
        "enabled": _truthy(enabled),
        "saved": False,
        "session_id": session,
        "collection_name": collection_name,
        "guarded": guard_present,
        "errors": [],
    }
    if not payload:
        status["errors"] = ["empty payload"]
        return {"session_state_write": status}
    if not state:
        status["reason"] = "state_not_found"
        return {**payload, "session_state_write": status}
    if not _truthy(enabled):
        status["reason"] = "disabled"
        return {**payload, "session_state_write": status}
    if not session:
        status["reason"] = "missing_session_id"
        status["errors"] = ["현재 실행의 session_id를 확인할 수 없어 세션 상태를 저장하지 않았습니다."]
        return {**payload, "session_state_write": status}
    if guard_present and not state_guard:
        status["reason"] = "invalid_session_state_guard"
        status["errors"] = ["세션 상태 보호 조건에 expected_turn_count와 expected_report_context_ref가 모두 필요합니다."]
        return {**payload, "session_state_write": status}

    uri = _clean(mongo_uri)
    database = _clean(mongo_database) or DEFAULT_DATABASE
    missing = []
    if not uri:
        missing.append("Mongo URI is empty.")
    if not database:
        missing.append("Mongo database is empty.")
    if not collection_name:
        missing.append("Mongo session state collection name is empty.")
    if missing:
        status["errors"] = missing
        return {**payload, "session_state_write": status}

    compact_state = _compact_state(state, preview_limit, max_history)
    compact_state.setdefault("session_id", session)
    client = None
    try:
        client, collection = _connect_collection(uri, database, collection_name)
        previous = collection.find_one({"_id": _document_id(session)}) or {}
        previous_turn_count = _positive_int(previous.get("turn_count") if isinstance(previous, dict) else 0, 0)
        if state_guard:
            expected_turn_count = int(state_guard["expected_turn_count"])
            expected_context_ref = str(state_guard["expected_report_context_ref"])
            actual_context_ref = _report_context_ref_from_document(previous)
            status["state_guard"] = {
                "expected_turn_count": expected_turn_count,
                "actual_turn_count": previous_turn_count,
                "expected_report_context_ref": expected_context_ref,
                "actual_report_context_ref": actual_context_ref,
            }
            if previous_turn_count != expected_turn_count or actual_context_ref != expected_context_ref:
                status["reason"] = "stale_session_state"
                status["errors"] = ["Report 후속 분석 중 세션의 active Report가 변경되어 이전 상태를 덮어쓰지 않았습니다."]
                return {**payload, "session_state_write": status}
        document = {
            "_id": _document_id(session),
            "session_id": session,
            "state_version": "agent-v1",
            "state": compact_state,
            "last_question": _question_from_payload(payload, response),
            "last_response_type": str(response.get("response_type") or payload.get("response_type") or ""),
            "turn_count": previous_turn_count + 1,
            "updated_at": datetime.now(timezone.utc).isoformat(),
        }
        if state_guard:
            conditional_filter = {
                "_id": document["_id"],
                "turn_count": int(state_guard["expected_turn_count"]),
                "state.current_data.report_context.context_ref": str(
                    state_guard["expected_report_context_ref"]
                ),
            }
            write_result = collection.replace_one(conditional_filter, document, upsert=False)
            if int(getattr(write_result, "matched_count", 0) or 0) != 1:
                status["reason"] = "stale_session_state"
                status["errors"] = ["Report 후속 분석 저장 직전에 active Report가 변경되어 상태 저장을 취소했습니다."]
                return {**payload, "session_state_write": status}
        else:
            collection.replace_one({"_id": document["_id"]}, document, upsert=True)
        status.update(
            {
                "saved": True,
                "turn_count": document["turn_count"],
                "preview_row_limit": preview_limit,
                "state_keys": sorted(compact_state.keys()),
                "errors": [],
            }
        )
        return {**payload, "session_state_write": status}
    except Exception as exc:
        status["errors"] = [str(exc)]
        return {**payload, "session_state_write": status}
    finally:
        close = getattr(client, "close", None)
        if callable(close):
            close()


# 함수 설명: `_compact_state()`는 상태에서 후속 단계에 필요한 정보만 남겨 payload와 token 크기를 줄입니다.
def _compact_state(state: Any, preview_limit: int, history_limit: int) -> dict[str, Any]:
    if not isinstance(state, dict):
        return {}
    del history_limit
    result: dict[str, Any] = {}
    request = state.get("request") if isinstance(state.get("request"), dict) else {}
    session_id = _session_id_from_state(state)
    if session_id:
        result["session_id"] = session_id
    last_question = state.get("last_question") or request.get("question")
    if last_question not in (None, ""):
        result["last_question"] = str(last_question)
    if state.get("last_answer_message") not in (None, ""):
        result["last_answer_message"] = str(state.get("last_answer_message"))
    result["current_data"] = _compact_current_data(state.get("current_data"), preview_limit)
    result["followup_source_results"] = [
        _compact_source_result(item, preview_limit)
        for item in state.get("followup_source_results", [])
        if isinstance(item, dict)
    ]
    for key in ("last_intent_plan", "last_applied_criteria"):
        value = state.get(key)
        if isinstance(value, dict) and value:
            result[key] = deepcopy(value)
    metadata_qa_inventory = _compact_metadata_qa_inventory(state.get("metadata_qa_inventory"))
    if metadata_qa_inventory:
        result["metadata_qa_inventory"] = metadata_qa_inventory
    runtime_source_refs = _compact_runtime_source_refs(
        state.get("runtime_source_refs"),
        result.get("current_data"),
        result.get("followup_source_results"),
    )
    if runtime_source_refs:
        result["runtime_source_refs"] = runtime_source_refs
    return _json_ready(result)


# 함수 설명: 현재 turn의 source alias에 해당하는 MongoDB 참조만 저장해 이전 데이터셋 참조가 세션 문서에 누적되지 않도록 합니다.
def _compact_runtime_source_refs(
    value: Any,
    current_data: Any,
    followup_sources: Any,
) -> dict[str, Any]:
    if not isinstance(value, dict):
        return {}
    allowed_aliases = {
        str(alias).strip()
        for alias in (current_data.get("source_aliases", []) if isinstance(current_data, dict) else [])
        if str(alias or "").strip()
    }
    for source in followup_sources if isinstance(followup_sources, list) else []:
        if not isinstance(source, dict):
            continue
        alias = str(source.get("source_alias") or "").strip()
        if alias:
            allowed_aliases.add(alias)
    return {
        str(alias): deepcopy(ref)
        for alias, ref in value.items()
        if str(alias) in allowed_aliases and isinstance(ref, dict)
    }


# 함수 설명: `_compact_current_data()`는 현재·데이터에서 후속 단계에 필요한 정보만 남겨 payload와 token 크기를 줄입니다.
def _compact_current_data(current_data: Any, preview_limit: int) -> dict[str, Any]:
    if not isinstance(current_data, dict):
        return {}
    result = deepcopy(current_data)
    rows = _rows_from(result)
    row_count = _positive_int(result.get("row_count"), len(rows))
    if rows:
        result["rows"] = deepcopy(rows[:preview_limit])
        result.pop("data", None)
        result["data_is_preview"] = row_count > len(result["rows"])
        if isinstance(result.get("data_ref"), dict):
            result.setdefault("data_ref_loaded", False)
            result.setdefault("data_ref_load_mode", "preview")
    result["row_count"] = row_count
    columns = result.get("columns") if isinstance(result.get("columns"), list) else []
    if not columns:
        columns = _rows_columns(rows)
    result["columns"] = columns
    if not isinstance(result.get("source_dataset_keys"), list):
        result["source_dataset_keys"] = []
    if not isinstance(result.get("source_aliases"), list):
        result["source_aliases"] = []
    return result


# 함수 설명: `_compact_source_result()`는 데이터 소스·결과에서 후속 단계에 필요한 정보만 남겨 payload와 token 크기를 줄입니다.
def _compact_source_result(source: dict[str, Any], preview_limit: int) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for key in (
        "source_alias",
        "dataset_key",
        "source_type",
        "columns",
        "data_ref",
        "row_count",
        "data_is_reference",
        "data_is_preview",
        "applied_params",
        "applied_filters",
    ):
        if source.get(key) not in (None, "", [], {}):
            result[key] = deepcopy(source[key])
    rows = _rows_from(source)
    if rows and not isinstance(result.get("data_ref"), dict):
        result["rows"] = deepcopy(rows[:preview_limit])
        result["row_count"] = _positive_int(result.get("row_count"), len(rows))
        result["data_is_preview"] = len(rows) > preview_limit
    return result


# 함수 설명: `_response_view()`는 VIEW에서 현재 단계가 사용할 필드만 추출해 표준 구조로 정리합니다.
def _response_view(payload: dict[str, Any]) -> dict[str, Any]:
    api_response = payload.get("api_response")
    return deepcopy(api_response) if isinstance(api_response, dict) else payload


# 함수 설명: `_session_state_guard()`는 입력 계약을 검증하고 해당 단계의 값을 안전하게 계산합니다.
def _session_state_guard(
    payload: dict[str, Any],
    response: dict[str, Any],
) -> tuple[dict[str, Any], bool]:
    """Return the optional optimistic-lock guard emitted by Report Flow 07-2."""

    raw: Any = None
    for source in (response, payload):
        candidate = source.get("session_state_guard") if isinstance(source, dict) else None
        if isinstance(candidate, dict):
            raw = candidate
            break
    if raw is None:
        return {}, False
    expected_ref = str(raw.get("expected_report_context_ref") or "").strip()
    expected_revision = raw.get("expected_turn_count")
    try:
        expected_revision = int(expected_revision)
    except Exception:
        return {}, True
    if expected_revision < 0 or not expected_ref:
        return {}, True
    return {
        "expected_turn_count": expected_revision,
        "expected_report_context_ref": expected_ref,
    }, True


# 함수 설명: `_report_context_ref_from_document()`는 입력 계약을 검증하고 해당 단계의 값을 안전하게 계산합니다.
def _report_context_ref_from_document(document: Any) -> str:
    if not isinstance(document, dict):
        return ""
    state = document.get("state") if isinstance(document.get("state"), dict) else {}
    current_data = state.get("current_data") if isinstance(state.get("current_data"), dict) else {}
    context = current_data.get("report_context") if isinstance(current_data.get("report_context"), dict) else {}
    return str(context.get("context_ref") or "").strip()


# 함수 설명: `_state_from_response()`는 분석 응답의 next_state/current_state에서 다음 턴에 저장할 상태를 우선순위대로 추출합니다.
def _state_from_response(payload: dict[str, Any], response: dict[str, Any]) -> dict[str, Any]:
    if isinstance(response.get("state"), dict):
        return deepcopy(response["state"])
    if isinstance(payload.get("state"), dict):
        return deepcopy(payload["state"])
    if isinstance(payload.get("next_state"), dict):
        return deepcopy(payload["next_state"])
    return {}


# 함수 설명: `_question_from_payload()`는 분석 payload의 request와 상태에서 현재 사용자 질문을 추출합니다.
def _question_from_payload(payload: dict[str, Any], response: dict[str, Any]) -> str:
    for source in (payload.get("request"), response.get("request"), payload, response):
        if isinstance(source, dict) and source.get("question") not in (None, ""):
            return str(source["question"])
    return ""


# 함수 설명: `_session_id_from_payload()`는 ID·원본·페이로드을 현재 컴포넌트의 표준 반환 형태로 변환합니다.
def _session_id_from_payload(payload: dict[str, Any]) -> str:
    for source in (payload.get("request"), payload):
        if not isinstance(source, dict):
            continue
        for key in ("session_id", "conversation_id", "chat_id", "thread_id"):
            if source.get(key) not in (None, ""):
                return str(source[key]).strip()
    return ""


# 함수 설명: `_session_id_from_state()`는 ID·원본·상태을 현재 컴포넌트의 표준 반환 형태로 변환합니다.
def _session_id_from_state(state: dict[str, Any]) -> str:
    for key in ("session_id", "conversation_id", "chat_id", "thread_id"):
        if state.get(key) not in (None, ""):
            return str(state[key]).strip()
    return ""


# 함수 설명: `_payload()`는 Langflow Data/Message 또는 일반 dict 입력에서 안전한 dict 페이로드 복사본을 꺼냅니다.
def _payload(value: Any) -> dict[str, Any]:
    if value is None:
        return {}
    data = getattr(value, "data", value)
    if isinstance(data, dict):
        return _copy_payload(data)
    text = getattr(value, "text", None) or getattr(value, "content", None)
    if isinstance(text, str):
        try:
            parsed = json.loads(text)
        except Exception:
            return {}
        return _copy_payload(parsed) if isinstance(parsed, dict) else {}
    if isinstance(value, str):
        try:
            parsed = json.loads(value)
        except Exception:
            return {}
        return _copy_payload(parsed) if isinstance(parsed, dict) else {}
    return {}


# 함수 설명: `_compact_metadata_qa_inventory()`는 데이터셋 목록 후속질문에 필요한 key·범위만 검증해 세션에 유지합니다.
def _compact_metadata_qa_inventory(value: Any) -> dict[str, Any]:
    raw = value if isinstance(value, dict) else {}
    if str(raw.get("contract_version") or "").strip() != METADATA_QA_INVENTORY_CONTRACT_VERSION:
        return {}
    raw_keys = raw.get("dataset_keys")
    if not isinstance(raw_keys, list) or not raw_keys or len(raw_keys) > MAX_METADATA_QA_INVENTORY_DATASETS:
        return {}
    dataset_keys = [str(item).strip() for item in raw_keys if str(item or "").strip()]
    if len(dataset_keys) != len(raw_keys) or len(set(dataset_keys)) != len(dataset_keys):
        return {}
    scope_raw = raw.get("scope") if isinstance(raw.get("scope"), dict) else {}
    scope: dict[str, list[str]] = {}
    for key in ("dataset_families", "source_types", "db_keys"):
        values = scope_raw.get(key)
        if not isinstance(values, list) or len(values) > MAX_METADATA_QA_INVENTORY_DATASETS:
            continue
        normalized = [str(item).strip() for item in values if str(item or "").strip()]
        if len(normalized) == len(values) and len(set(normalized)) == len(normalized):
            scope[key] = normalized
    result: dict[str, Any] = {
        "contract_version": METADATA_QA_INVENTORY_CONTRACT_VERSION,
        "dataset_keys": dataset_keys,
    }
    if scope:
        result["scope"] = scope
    return result


# 함수 설명: `_copy_payload()`는 제어 필드는 깊게 복사하되 대용량 런타임 행 버퍼는 최종 정리 노드까지 공유합니다.
def _copy_payload(data: dict[str, Any]) -> dict[str, Any]:
    payload = {
        key: deepcopy(item)
        for key, item in data.items()
        if key not in RUNTIME_BUFFER_KEYS
    }
    for key in RUNTIME_BUFFER_KEYS:
        if key in data:
            payload[key] = data[key]
    return payload


# 함수 설명: `_connect_collection()`는 짧은 server selection timeout으로 MongoDB client와 대상 collection을 생성합니다.
def _connect_collection(uri: str, database: str, collection_name: str) -> tuple[Any, Any]:
    pymongo = import_module("pymongo")
    client = pymongo.MongoClient(uri, serverSelectionTimeoutMS=5000)
    return client, client[database][collection_name]


# 함수 설명: `_collection_name()`는 standalone 노드 입력과 코드 기본값으로 실제 세션 상태 collection 이름을 결정합니다.
def _collection_name(value: Any) -> str:
    return _clean(value) or DEFAULT_SESSION_COLLECTION


# 함수 설명: `_document_id()`는 session_id로 `session_state:{id}` 형식의 canonical 문서 ID를 만듭니다.
def _document_id(session_id: str) -> str:
    return f"session_state:{session_id}"


# 함수 설명: `_rows_from()`는 복합 데이터에서 저장/표시에 사용할 dict 행 목록을 추출합니다.
def _rows_from(value: dict[str, Any]) -> list[dict[str, Any]]:
    rows = value.get("rows")
    if not isinstance(rows, list):
        rows = value.get("preview_rows")
    if not isinstance(rows, list):
        rows = value.get("data")
    if not isinstance(rows, list):
        return []
    return [row for row in rows if isinstance(row, dict)]


# 함수 설명: `_rows_columns()`는 행 목록과 명시 컬럼을 함께 정규화해 표준 rows/columns 쌍을 만듭니다.
def _rows_columns(rows: list[dict[str, Any]]) -> list[str]:
    columns: list[str] = []
    for row in rows:
        for key in row:
            text = str(key)
            if text not in columns:
                columns.append(text)
    return columns


# 함수 설명: `_truthy()`는 입력값이 활성/참 의미로 해석되는지 공통 규칙으로 판정합니다.
def _truthy(value: Any) -> bool:
    if isinstance(value, bool):
        return value
    return str(value).strip().lower() not in {"", "0", "false", "no", "n", "off", "disabled"}


# 함수 설명: `_positive_int()`는 입력 숫자를 1 이상의 정수로 제한해 preview·history 한도에 사용합니다.
def _positive_int(value: Any, default: int) -> int:
    try:
        parsed = int(value)
    except Exception:
        parsed = default
    return max(0, parsed)


# 함수 설명: `_clean()`는 선택 입력을 안전한 문자열로 바꾸고 불필요한 앞뒤 공백을 제거합니다.
def _clean(value: Any) -> str:
    return str(value or "").strip()


# 함수 설명: `_json_ready()`는 datetime·Decimal·NaN 등 JSON이 직접 표현하지 못하는 값을 안전한 기본형으로 재귀 변환합니다.
def _json_ready(value: Any) -> Any:
    try:
        return json.loads(json.dumps(value, ensure_ascii=False, default=str))
    except Exception:
        return value


# Langflow 컴포넌트 클래스: inputs/outputs가 캔버스 포트와 JSON edge 계약을 정의합니다.
# 실제 업무 규칙은 위의 주요 함수에 두어 UI 실행과 단위 테스트가 같은 로직을 사용합니다.
class MongoDBSessionStateWriter(Component):
    display_name = "01 MongoDB 세션 상태 저장기"
    description = "flow 실행 후 다음 질문에서 사용할 compact state를 MongoDB에 저장합니다."
    icon = "DatabaseZap"
    name = "MongoDBSessionStateWriter"
    inputs = [
        DataInput(name="response_payload", display_name="응답 페이로드", required=True),
        MessageTextInput(name="mongo_uri", display_name="Mongo URI 선택값", value="", advanced=False),
        MessageTextInput(name="mongo_database", display_name="Mongo Database 선택값", value=DEFAULT_DATABASE, advanced=False),
        MessageTextInput(name="session_collection_name", display_name="세션 상태 컬렉션", value=DEFAULT_SESSION_COLLECTION, advanced=False),
        DropdownInput(name="enabled", display_name="사용 여부", options=ENABLED_OPTIONS, value="true", advanced=True),
        MessageTextInput(name="preview_row_limit", display_name="Preview 행 제한", value=str(DEFAULT_PREVIEW_ROW_LIMIT), advanced=True),
        MessageTextInput(name="history_limit", display_name="History 제한", value=str(DEFAULT_HISTORY_LIMIT), advanced=True),
    ]
    outputs = [Output(name="payload_out", display_name="페이로드 출력", method="build_payload", types=["Data"])]

    # Langflow 출력 함수: '페이로드 출력 (payload_out)' 포트가 요청될 때 실행됩니다.
    # 핵심 처리 결과를 Langflow Data/Message 형식으로 감싸 다음 노드에 전달합니다.
    def build_payload(self) -> Data:
        payload = write_session_state(
            getattr(self, "response_payload", None),
            getattr(self, "mongo_uri", ""),
            getattr(self, "mongo_database", ""),
            getattr(self, "session_collection_name", ""),
            getattr(self, "enabled", "true"),
            getattr(self, "preview_row_limit", str(DEFAULT_PREVIEW_ROW_LIMIT)),
            getattr(self, "history_limit", str(DEFAULT_HISTORY_LIMIT)),
        )
        self.status = payload.get("session_state_write", {})
        return Data(data=payload)

# -*- coding: utf-8 -*-
# =============================================================================
# 컴포넌트 개요: 05 메타데이터 QA 메시지 어댑터
# 역할: 메타데이터 QA 페이로드를 Playground 채팅용 한국어 markdown 메시지로 변환합니다.
# 주요 입력: 페이로드 (payload) · 필수
# 주요 출력: 메시지 (message)
# 처리 흐름: QA 결과를 답변·표·SQL·관련 메타데이터·경고 순서의 Markdown Message 하나로 렌더링합니다.
# 유지보수 포인트: 이 노드만 최종 Chat Output에 연결해 중간 질문이나 JSON이 대화 기록에 중복 출력되지 않게 합니다.
# =============================================================================

from __future__ import annotations

import json
from copy import deepcopy
from typing import Any

from lfx.custom.custom_component.component import Component
from lfx.io import DataInput, Output
from lfx.schema.message import Message

TABLE_LIMIT = 12
CELL_LIMIT = 160


# 주요 함수: 구조화 결과를 사용자가 읽을 수 있는 단일 Markdown Message로 변환합니다.
# Langflow 클래스와 단위 테스트가 같은 업무 규칙을 쓰도록 일반 Python 값 중심으로 처리합니다.
def build_message(payload_value: Any) -> str:
    payload = _payload(payload_value)
    if not payload:
        return ""
    answer_sections = payload.get("answer_sections") if isinstance(payload.get("answer_sections"), dict) else {}
    if answer_sections:
        sections = _message_from_answer_sections(payload, answer_sections)
        if sections:
            return "\n\n".join(sections)

    sections = []
    answer = str(payload.get("answer_message") or payload.get("message") or "").strip()
    if answer:
        sections.append("### 답변\n" + answer)

    sql_section = _sql_section(_dict(payload.get("metadata_qa")).get("sql_blocks"))
    if sql_section:
        sections.append(sql_section)

    table_section = _table_section(_dict(payload.get("data")))
    if table_section:
        sections.append(table_section)

    refs_section = _refs_section(_dict(payload.get("metadata_qa")).get("source_refs"))
    if refs_section:
        sections.append(refs_section)

    warning_section = _warning_section(_dict(payload.get("trace")))
    if warning_section:
        sections.append(warning_section)
    return "\n\n".join(sections) if sections else json.dumps(payload, ensure_ascii=False, default=str)


# 함수 설명: `_message_from_answer_sections()`는 원본·답변·응답 section을 최종 Message에 넣을 독립 Markdown section으로 렌더링합니다.
def _message_from_answer_sections(payload: dict[str, Any], answer_sections: dict[str, Any]) -> list[str]:
    sections: list[str] = []
    summary = _dict(answer_sections.get("summary"))
    answer = str(summary.get("headline") or payload.get("answer_message") or payload.get("message") or "").strip()
    if answer:
        sections.append("### 답변\n" + answer)

    key_points_section = _key_points_section(answer_sections.get("key_points"))
    if key_points_section:
        sections.append(key_points_section)

    detail_section = _detail_table_section(_dict(answer_sections.get("detail_table")), _dict(payload.get("data")))
    if detail_section:
        sections.append(detail_section)

    sql_section = _sql_section(answer_sections.get("sql_blocks"))
    if sql_section:
        sections.append(sql_section)

    route_hint_section = _route_hint_section(_dict(answer_sections.get("route_hint")))
    if route_hint_section:
        sections.append(route_hint_section)

    if bool(answer_sections.get("show_related_items")):
        related_section = _refs_section(answer_sections.get("related_items") or _dict(payload.get("metadata_qa")).get("source_refs"))
        if related_section:
            sections.append(related_section)

    warning_section = _section_warnings(answer_sections.get("warnings")) or _warning_section(_dict(payload.get("trace")))
    if warning_section:
        sections.append(warning_section)
    return sections


# 함수 설명: `_key_points_section()`는 핵심 항목·응답 section을 최종 Message에 넣을 독립 Markdown section으로 렌더링합니다.
def _key_points_section(value: Any) -> str:
    points = [str(item).strip() for item in value if str(item or "").strip()] if isinstance(value, list) else []
    if not points:
        return ""
    lines = ["### 한눈에 보기"]
    lines.extend(f"- {point}" for point in points[:6])
    return "\n".join(lines)


# 함수 설명: `_detail_table_section()`는 표·응답 section을 최종 Message에 넣을 독립 Markdown section으로 렌더링합니다.
def _detail_table_section(detail_table: dict[str, Any], data: dict[str, Any]) -> str:
    rows = _row_list(detail_table.get("rows")) or (_row_list(data.get("rows")) if detail_table.get("row_source") == "data.rows" else [])
    columns = _string_list(detail_table.get("columns")) or _columns_from_rows(rows)
    if not rows:
        return ""
    title = str(detail_table.get("title") or "관련 메타데이터").strip()
    display_limit = _int(detail_table.get("display_limit"), TABLE_LIMIT)
    preview_rows = rows[:display_limit]
    row_count = int(detail_table.get("row_count") or len(rows))
    note = f"\n\n총 {row_count}건 중 {len(preview_rows)}건을 표시했습니다." if row_count > len(preview_rows) else f"\n\n총 {row_count}건입니다."
    return f"### {title}\n" + _markdown_table(preview_rows, columns) + note


# 함수 설명: `_route_hint_section()`는 힌트·응답 section을 최종 Message에 넣을 독립 Markdown section으로 렌더링합니다.
def _route_hint_section(route_hint: dict[str, Any]) -> str:
    if not route_hint:
        return ""
    message = str(route_hint.get("message") or "").strip()
    target_route = str(route_hint.get("target_route") or "").strip()
    lines = ["### 권장 실행 경로"]
    if target_route:
        lines.append(f"- 대상 route: `{target_route}`")
    if message:
        lines.append(f"- 안내: {message}")
    return "\n".join(lines) if len(lines) > 1 else ""


# 함수 설명: `_section_warnings()`는 경고을 최종 Message에 넣을 독립 Markdown section으로 렌더링합니다.
def _section_warnings(value: Any) -> str:
    warnings = [item for item in value if isinstance(item, dict)] if isinstance(value, list) else []
    if not warnings:
        return ""
    lines = ["### 참고"]
    for item in warnings[:8]:
        message = str(item.get("message") or item.get("type") or "").strip()
        if message:
            lines.append(f"- {message}")
    return "\n".join(lines) if len(lines) > 1 else ""


# 함수 설명: `_sql_section()`는 응답 section을 최종 Message에 넣을 독립 Markdown section으로 렌더링합니다.
def _sql_section(sql_blocks_value: Any) -> str:
    blocks = [block for block in sql_blocks_value if isinstance(block, dict)] if isinstance(sql_blocks_value, list) else []
    if not blocks:
        return ""
    lines = ["### 등록된 Query Template"]
    for block in blocks[:3]:
        label = str(block.get("label") or "query_template").strip()
        sql = str(block.get("sql") or "").strip()
        if not sql:
            continue
        lines.append(f"#### {label}")
        lines.append("```sql\n" + sql + "\n```")
    return "\n".join(lines)


# 함수 설명: `_table_section()`는 구조화 rows/columns를 최종 답변의 표 section 계약으로 변환합니다.
def _table_section(data: dict[str, Any]) -> str:
    rows = _row_list(data.get("rows"))
    columns = _string_list(data.get("columns")) or _columns_from_rows(rows)
    if not rows:
        return ""
    preview_rows = rows[:TABLE_LIMIT]
    note = f"\n\n총 {len(rows)}건 중 {len(preview_rows)}건을 표시했습니다." if len(rows) > len(preview_rows) else f"\n\n총 {len(rows)}건입니다."
    return "### 관련 메타데이터\n" + _markdown_table(preview_rows, columns) + note


# 함수 설명: `_refs_section()`는 응답 section을 최종 Message에 넣을 독립 Markdown section으로 렌더링합니다.
def _refs_section(value: Any) -> str:
    refs = [ref for ref in value if isinstance(ref, dict)] if isinstance(value, list) else []
    if not refs:
        return ""
    labels = []
    for ref in refs[:10]:
        metadata_type = str(ref.get("metadata_type") or "").strip()
        section = str(ref.get("section") or "").strip()
        key = str(ref.get("key") or "").strip()
        labels.append(":".join(part for part in (metadata_type, section, key) if part))
    return "### 사용한 메타데이터\n" + "\n".join(f"- `{label}`" for label in labels if label)


# 함수 설명: `_warning_section()`는 응답 section을 최종 Message에 넣을 독립 Markdown section으로 렌더링합니다.
def _warning_section(trace: dict[str, Any]) -> str:
    warnings = _list(trace.get("warnings"))
    errors = _list(trace.get("errors"))
    if not warnings and not errors:
        return ""
    lines = ["### 경고/오류"]
    for item in warnings[:8]:
        lines.append(f"- 경고: `{_display(item)}`")
    for item in errors[:8]:
        lines.append(f"- 오류: `{_display(item)}`")
    return "\n".join(lines)


# 함수 설명: `_markdown_table()`는 컬럼과 행을 길이 제한·escape 규칙이 적용된 Markdown 표로 렌더링합니다.
def _markdown_table(rows: list[dict[str, Any]], columns: list[str]) -> str:
    header = "| " + " | ".join(_escape(column) for column in columns) + " |"
    divider = "| " + " | ".join("---" for _ in columns) + " |"
    body = []
    for row in rows:
        body.append("| " + " | ".join(_escape(row.get(column, "")) for column in columns) + " |")
    return "\n".join([header, divider] + body)


# 함수 설명: `_payload()`는 Langflow Data/Message 또는 일반 dict 입력에서 안전한 dict 페이로드 복사본을 꺼냅니다.
def _payload(value: Any) -> dict[str, Any]:
    data = getattr(value, "data", value)
    return deepcopy(data) if isinstance(data, dict) else {}


# 함수 설명: `_dict()`는 입력값이 dict인지 확인하고 아니면 빈 dict를 반환해 후속 key 접근 오류를 막습니다.
def _dict(value: Any) -> dict[str, Any]:
    return value if isinstance(value, dict) else {}


# 함수 설명: `_list()`는 입력값을 list로 정규화하고 목록이 아닌 값은 안전한 기본 목록으로 바꿉니다.
def _list(value: Any) -> list[Any]:
    return value if isinstance(value, list) else []


# 함수 설명: `_row_list()`는 여러 입력 형태에서 dict인 행만 골라 표준 행 목록으로 반환합니다.
def _row_list(value: Any) -> list[dict[str, Any]]:
    return [dict(row) for row in value if isinstance(row, dict)] if isinstance(value, list) else []


# 함수 설명: `_string_list()`는 여러 형태의 입력에서 비어 있지 않은 문자열만 뽑아 중복 없는 목록으로 정리합니다.
def _string_list(value: Any) -> list[str]:
    return [str(item) for item in value if str(item or "").strip()] if isinstance(value, list) else []


# 함수 설명: `_columns_from_rows()`는 행 목록의 key 등장 순서를 유지하면서 결과 테이블의 컬럼 목록을 계산합니다.
def _columns_from_rows(rows: list[dict[str, Any]]) -> list[str]:
    columns = []
    for row in rows:
        for key in row:
            if key not in columns:
                columns.append(str(key))
    return columns


# 함수 설명: `_escape()`는 Markdown 표 셀을 깨뜨리는 구분자와 줄바꿈 문자를 안전하게 escape합니다.
def _escape(value: Any) -> str:
    text = _display(value).replace("\n", "<br>").replace("|", "\\|")
    return text[: CELL_LIMIT - 3] + "..." if len(text) > CELL_LIMIT else text


# 함수 설명: `_display()`는 표시값을 Markdown 또는 사용자 화면에서 안전하게 읽을 수 있는 표현으로 변환합니다.
def _display(value: Any) -> str:
    if isinstance(value, (dict, list)):
        return json.dumps(value, ensure_ascii=False, default=str)
    return "" if value is None else str(value)


# 함수 설명: `_int()`는 문자열이나 숫자 입력을 정수로 변환하고 실패하면 안전한 기본값을 사용합니다.
def _int(value: Any, default: int) -> int:
    try:
        return max(1, int(value))
    except Exception:
        return default


# Langflow 컴포넌트 클래스: inputs/outputs가 캔버스 포트와 JSON edge 계약을 정의합니다.
# 실제 업무 규칙은 위의 주요 함수에 두어 UI 실행과 단위 테스트가 같은 로직을 사용합니다.
class MetadataQaMessageAdapter(Component):
    display_name = "05 메타데이터 QA 메시지 어댑터"
    description = "메타데이터 QA 페이로드를 Playground 채팅용 한국어 markdown 메시지로 변환합니다."
    inputs = [DataInput(name="payload", display_name="페이로드", required=True)]
    outputs = [Output(name="message", display_name="메시지", method="build_output_message", types=["Message"])]

    # Langflow 출력 함수: '메시지 (message)' 포트가 요청될 때 실행됩니다.
    # 핵심 처리 결과를 Langflow Data/Message 형식으로 감싸 다음 노드에 전달합니다.
    def build_output_message(self) -> Message:
        return Message(text=build_message(getattr(self, "payload", None)))

# -*- coding: utf-8 -*-
# =============================================================================
# 컴포넌트 개요: 02 Agent 직접 반환 결과 어댑터
# 역할: Langflow 1.11 Agent가 하위 Flow 내부 LLM 이벤트를 최종 메시지에 섞는 현상을 차단합니다.
# 주요 입력: Agent 응답(agent_message), 도구 최종 답변 우선(prefer_tool_result)
# 주요 출력: 정리된 메시지(message)
# 처리 흐름: 성공한 ToolContent.output의 content만 골라 새 Message로 만들고, 원본 Agent content_blocks는 전달하지 않습니다.
# 유지보수 포인트: Tool 응답의 content/message/output/data 중 표시 가능한 텍스트만 허용하며 임의 JSON 문자열화는 하지 않습니다.
# =============================================================================
"""Normalize a direct-return Agent result before it reaches Chat Output.

Langflow 1.11 Agent graphs forward nested child-flow model events through the
parent Agent event stream.  When a Run Flow tool uses ``return_direct=True``,
the Agent's own ``text`` can therefore contain an internal child LLM payload
instead of the tool's final answer.  The successful tool result is still
available in ``Message.content_blocks`` as ``ToolContent.output``.

This standalone component deliberately creates a new Message containing only
that final tool text.  It is placed between Agent and Chat Output so the
intermediate Agent message is not persisted or rendered by the Playground.
"""

from __future__ import annotations

from collections.abc import Mapping
from typing import Any

from lfx.custom.custom_component.component import Component
from lfx.io import BoolInput, HandleInput, Output
from lfx.schema.message import Message


_MISSING = object()
_FAILED_TOOL_STATUSES = {"error", "failed", "failure", "cancelled", "canceled"}


# 주요 함수: Langflow/Pydantic 객체와 JSON dict에서 같은 방식으로 필드 값을 읽습니다.
def _value(item: Any, key: str, default: Any = None) -> Any:
    """Read a field from Langflow/Pydantic objects and JSON-compatible dicts."""

    if isinstance(item, Mapping):
        return item.get(key, default)
    return getattr(item, key, default)


# 주요 함수: Pydantic content 객체를 안전하게 mapping 형태로 정규화합니다.
def _as_mapping(item: Any) -> Mapping[str, Any] | None:
    if isinstance(item, Mapping):
        return item
    model_dump = getattr(item, "model_dump", None)
    if callable(model_dump):
        try:
            dumped = model_dump()
        except Exception:  # pragma: no cover - defensive against third-party content objects
            return None
        return dumped if isinstance(dumped, Mapping) else None
    return None


# 주요 함수: 중첩된 rich content를 표시 순서대로 순회합니다.
def _walk_content(items: Any):
    """Yield content blocks in display order, including nested rich content."""

    if isinstance(items, (list, tuple)):
        for item in items:
            yield from _walk_content(item)
        return
    if items is None:
        return
    yield items
    children = _value(items, "contents", None)
    if isinstance(children, (list, tuple)):
        for child in children:
            yield from _walk_content(child)


# 주요 함수: ToolContent 또는 호환 가능한 직렬화 Tool 블록인지 판별합니다.
def _is_tool_content(item: Any) -> bool:
    item_type = str(_value(item, "type", "") or "").casefold()
    if item_type in {"tool", "tool_use", "tool_call"}:
        return True
    output = _value(item, "output", _MISSING)
    return output is not _MISSING and bool(_value(item, "name", "") or _value(item, "tool_call_id", ""))


# 주요 함수: 임의 JSON을 노출하지 않고 사용자에게 표시할 수 있는 텍스트만 추출합니다.
def _text_from_value(value: Any, *, depth: int = 0) -> str:
    """Extract a human-visible answer without stringifying arbitrary JSON."""

    if value is None or depth > 6:
        return ""
    if isinstance(value, str):
        return value.strip()
    if isinstance(value, bytes):
        try:
            return value.decode("utf-8").strip()
        except UnicodeDecodeError:
            return ""

    # A child Run Flow may return a Message directly instead of a tool dict.
    text = _value(value, "text", _MISSING)
    if text is not _MISSING and text is not value:
        extracted = _text_from_value(text, depth=depth + 1)
        if extracted:
            return extracted

    mapping = _as_mapping(value)
    if mapping is not None:
        for key in ("content", "message", "output", "data"):
            candidate = mapping.get(key, _MISSING)
            if candidate is _MISSING or candidate is value:
                continue
            extracted = _text_from_value(candidate, depth=depth + 1)
            if extracted:
                return extracted
        return ""

    if isinstance(value, (list, tuple)):
        parts = [_text_from_value(item, depth=depth + 1) for item in value]
        return "\n".join(part for part in parts if part).strip()
    return ""


# 주요 함수: 마지막 성공 Tool 결과와 오류 상태를 찾아 직접 반환 후보를 만듭니다.
def _last_tool_result(content_blocks: Any) -> tuple[str, bool, str]:
    """Return (successful_text, saw_tool, last_clean_error_text)."""

    successful_text = ""
    saw_tool = False
    error_text = ""
    for item in _walk_content(content_blocks):
        if not _is_tool_content(item):
            continue
        saw_tool = True
        error = _value(item, "error", None)
        output = _value(item, "output", None)
        status = str(_value(output, "status", "") or "").casefold()
        if error or status in _FAILED_TOOL_STATUSES:
            error_text = _text_from_value(error) or _text_from_value(output)
            continue
        extracted = _text_from_value(output)
        if extracted:
            successful_text = extracted
    return successful_text, saw_tool, error_text


# 주요 함수: 세션 문맥만 보존한 새 Message를 만들어 원본 Agent 이벤트를 끊습니다.
def _message_with_context(source: Any, text: str) -> Message:
    """Make a clean Message while retaining the session used by Chat Output."""

    kwargs: dict[str, Any] = {"text": text}
    for field_name in ("session_id", "context_id"):
        value = _value(source, field_name, None)
        if value not in (None, ""):
            kwargs[field_name] = value
    return Message(**kwargs)


# 주요 함수: return_direct Tool의 최종 답변을 선택하고 하위 LLM JSON 누출을 방지합니다.
def build_direct_tool_result(agent_message: Any, *, prefer_tool_result: bool = True) -> Message:
    """Select the final tool answer and prevent nested LLM JSON from leaking."""

    tool_text, saw_tool, tool_error = _last_tool_result(_value(agent_message, "content_blocks", None))
    agent_text = _text_from_value(_value(agent_message, "text", ""))

    if prefer_tool_result and tool_text:
        return _message_with_context(agent_message, tool_text)
    if saw_tool and not tool_text:
        fallback = tool_error or "도구 실행은 완료되었지만 표시할 최종 답변을 받지 못했습니다."
        return _message_with_context(agent_message, fallback)
    return _message_with_context(agent_message, agent_text)


# Langflow 컴포넌트 클래스: 입력 Agent Message에서 성공 Tool 답변만 선택해 Chat Output으로 보냅니다.
class AgentDirectToolResultAdapter(Component):
    display_name = "02 Agent 직접 반환 결과 어댑터"
    description = "return_direct 도구의 최종 답변만 선택하여 하위 Flow 내부 이벤트가 Playground 답변에 섞이지 않게 합니다."
    icon = "Route"
    name = "AgentDirectToolResultAdapter"

    inputs = [
        HandleInput(
            name="agent_message",
            display_name="Agent 응답",
            info="Agent의 response Message를 연결합니다.",
